"use client";

import { useEffect, useMemo, useRef, useState, type FormEvent } from "react";
import { BOARD_COLUMNS, formatActualCost, formatEstimatedCost, formatRelativeTime, getColumnLabel, type ActivityItem, type AgentRun, type DashboardData, type Project, type ReasoningEffort, type RunEvent, type Task, type TaskStatus } from "@/lib/domain";
import { Icon, type IconName } from "./icons";

const EMPTY_DATA: DashboardData = { projects: [], tasks: [], runs: [], activity: [], runEvents: [], runtime: { executionMode: "demo", liveReady: false, reason: null, reasoning: { providerId: "", modelId: "", supportedEfforts: [] } } };

const statusStyles: Record<TaskStatus, { dot: string; badge: string }> = {
  inbox: { dot: "bg-slate-400", badge: "border-slate-500/30 bg-slate-500/10 text-slate-300" },
  ready: { dot: "bg-cyan-300", badge: "border-cyan-300/25 bg-cyan-300/10 text-cyan-200" },
  in_progress: { dot: "bg-amber-300", badge: "border-amber-300/25 bg-amber-300/10 text-amber-200" },
  human_review: { dot: "bg-rose-300", badge: "border-rose-300/25 bg-rose-300/10 text-rose-200" },
  blocked: { dot: "bg-red-300", badge: "border-red-300/25 bg-red-300/10 text-red-200" },
  done: { dot: "bg-emerald-300", badge: "border-emerald-300/25 bg-emerald-300/10 text-emerald-200" },
};

const priorityLabels = ["P0", "P1", "P2", "P3"];

function agentLabel(state: Task["agentState"]) {
  return { idle: "No agent", running: "Run active", waiting: "Paused", failed: "Run failed", succeeded: "Agent done" }[state];
}

function agentTone(state: Task["agentState"]) {
  return { idle: "text-slate-500", running: "text-amber-300", waiting: "text-rose-300", failed: "text-red-300", succeeded: "text-violet-300" }[state];
}

function actualCostLabel(task: Task) {
  if (task.actualCostStatus === "not_started") return "Actual · not run";
  if (task.actualCostStatus === "pending") return "Actual · pending";
  if (task.actualCostStatus === "unavailable") return "Actual · unavailable";
  return `${task.actualCostStatus === "partial" ? "Actual · partial" : "Actual"} ${formatActualCost(task.actualCostUsd ?? 0)}`;
}

function ProjectMark({ project, large = false }: { project: Project; large?: boolean }) {
  return <div className={`${large ? "h-11 w-11 text-sm" : "h-8 w-8 text-[10px]"} flex shrink-0 items-center justify-center rounded-[11px] font-extrabold tracking-tight text-[#101318]`} style={{ background: project.accent }}>{project.initials}</div>;
}

function StatusPill({ task }: { task: Task }) {
  return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-1 text-[10px] font-semibold ${statusStyles[task.status].badge}`}><span className={`h-1.5 w-1.5 rounded-full ${statusStyles[task.status].dot}`} />{getColumnLabel(task.status)}</span>;
}

function Metric({ label, value, detail, accent, icon }: { label: string; value: string; detail: string; accent: string; icon: IconName }) {
  return <div className="relative overflow-hidden rounded-2xl border border-white/[.08] bg-[#191d22]/85 p-4 shadow-[0_12px_40px_rgba(0,0,0,.12)]"><div className="absolute -right-5 -top-8 h-20 w-20 rounded-full opacity-10 blur-2xl" style={{ background: accent }} /><div className="flex items-start justify-between"><span className="eyebrow">{label}</span><Icon name={icon} size={15} className="text-slate-500" /></div><div className="mt-3 flex items-end gap-2"><strong className="text-2xl font-bold tracking-tight text-[#f3f5f0]">{value}</strong><span className="mono mb-0.5 text-[10px] text-slate-500">{detail}</span></div><div className="mt-3 h-1 overflow-hidden rounded-full bg-white/[.06]"><div className="h-full rounded-full" style={{ background: accent, width: `${Math.max(15, Math.min(100, Number(value) * 12))}%` }} /></div></div>;
}

function ActivityIcon({ item }: { item: ActivityItem }) {
  const icon: IconName = item.type.includes("pull") ? "git-branch" : item.type.includes("human") ? "user" : item.type.includes("run") ? "bot" : item.type.includes("sync") ? "refresh" : item.type.includes("task") ? "plus" : "activity";
  return <div className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-xl border border-white/[.08] bg-white/[.035] ${item.tone === "amber" ? "text-amber-300" : item.tone === "violet" ? "text-violet-300" : item.tone === "rose" ? "text-rose-300" : item.tone === "green" ? "text-emerald-300" : "text-cyan-300"}`}><Icon name={icon} size={14} /></div>;
}

function RunConsole({ run, events, expanded = false, onExpand }: { run: AgentRun; events: RunEvent[]; expanded?: boolean; onExpand?: () => void }) {
  const modeLive = run.executionMode === "live";
  const modeLabel = modeLive ? (run.isActive ? "Live" : "Live history") : "Demo";
  const usageLabel = run.actualCostUsd === null ? run.costSource === "pending" ? "Usage pending" : "Usage unavailable" : `${formatActualCost(run.actualCostUsd)} · ${run.costSource}`;
  const textSize = expanded ? "text-xs" : "text-[10px]";
  const eventsToShow = expanded ? events : events.slice(0, 8);
  return <div className={`${expanded ? "rounded-2xl border border-white/[.08] bg-[#111519] p-5 sm:p-6" : "mt-5 rounded-2xl border border-white/[.08] bg-[#111519] p-4"}`}>
    <div className="flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-2"><span className="eyebrow">Run console</span><span className={`rounded-full border px-2 py-1 text-[9px] font-bold uppercase tracking-[.12em] ${modeLive ? "border-cyan-300/20 bg-cyan-300/10 text-cyan-200" : "border-amber-300/20 bg-amber-300/10 text-amber-200"}`}>{modeLabel}</span></div><div className="flex items-center gap-3"><span className="mono text-[9px] text-slate-600">{run.id.slice(0, 16)}</span>{onExpand && <button type="button" onClick={onExpand} aria-label="Open live history" className="inline-flex items-center gap-1.5 rounded-lg border border-cyan-300/20 bg-cyan-300/[.06] px-2.5 py-1.5 text-[10px] font-semibold text-cyan-200 transition hover:border-cyan-300/40 hover:bg-cyan-300/10 hover:text-cyan-100"><Icon name="maximize" size={12} />Open live history</button>}</div></div>
    {!modeLive && <p className="mt-3 rounded-xl border border-amber-300/15 bg-amber-300/[.06] p-3 text-[10px] leading-relaxed text-amber-100/70">Simulation only — no files, commits, branches, or PRs were created.</p>}
    <div className="mt-3 rounded-xl border border-cyan-300/10 bg-cyan-300/[.04] p-3 sm:p-4"><div className="eyebrow text-cyan-200/70">Provider accounting</div><div className={`mono mt-2 truncate ${expanded ? "text-xs" : "text-[10px]"} text-slate-300`}>{run.providerId || "provider unknown"} / {run.modelId || "model unknown"}</div><div className={`mt-1 ${textSize} text-slate-500`}>Reasoning · {run.reasoningEffort ?? "Default"}</div><div className={`mt-1 ${textSize} leading-relaxed text-slate-500`}>{run.inputTokens.toLocaleString()} input · {run.outputTokens.toLocaleString()} output · {run.cacheReadTokens.toLocaleString()} cached read · {run.cacheWriteTokens.toLocaleString()} cached write</div><div className="mt-2 text-xs font-semibold text-cyan-200">{usageLabel}</div></div>
    <div className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-2"><div className="rounded-xl border border-white/[.06] bg-white/[.025] p-3 sm:p-4"><div className="eyebrow">Workspace</div><div className={`mono mt-2 truncate ${textSize} text-slate-400`}>{run.workspacePath ?? "Not prepared"}</div></div><div className="rounded-xl border border-white/[.06] bg-white/[.025] p-3 sm:p-4"><div className="eyebrow">Commit</div><div className={`mono mt-2 truncate ${textSize} text-slate-400`}>{run.commitSha ?? "No commit yet"}</div></div></div>
    {run.changedFiles.length > 0 && <div className="mt-3"><div className="eyebrow">Changed files</div><div className="mt-2 space-y-1">{run.changedFiles.slice(0, expanded ? undefined : 6).map((file) => <div key={file} className={`mono truncate ${textSize} text-slate-400`}><span className="mr-2 text-cyan-300">•</span>{file}</div>)}</div></div>}
    {run.checks.length > 0 && <div className="mt-4"><div className="eyebrow">Checks</div><div className="mt-2 space-y-1.5">{run.checks.map((check) => <div key={`${check.name}-${check.command}`} className={`flex items-center justify-between gap-2 ${textSize}`}><span className="truncate text-slate-400">{check.name}</span><span className={check.status === "passed" ? "text-emerald-300" : check.status === "failed" ? "text-rose-300" : "text-amber-300"}>{check.status}</span></div>)}</div></div>}
    <div className="mt-4"><div className="eyebrow">Event trace</div><div className={`scrollbar mt-2 space-y-3 overflow-y-auto ${expanded ? "max-h-[calc(100vh-380px)]" : "max-h-32"}`}>{eventsToShow.map((event) => <div key={event.id} className="border-l border-white/[.1] pl-3"><div className={`${expanded ? "text-sm" : "text-[10px]"} font-semibold text-slate-300`}>{event.message}</div><div className={`mt-0.5 ${expanded ? "text-xs" : "text-[9px]"} leading-relaxed text-slate-500`}>{event.detail}</div><div className="mono mt-1 text-[9px] text-slate-700">{formatRelativeTime(event.createdAt)}</div></div>)}{!events.length && <div className="text-xs text-slate-600">No events have been recorded yet.</div>}</div></div>
  </div>;
}

function TaskCard({ task, onSelect, onStart }: { task: Task; onSelect: () => void; onStart: () => void }) {
  return <article onClick={onSelect} className="group relative cursor-pointer rounded-2xl border border-white/[.08] bg-[#1b2026] p-3.5 transition duration-200 hover:-translate-y-0.5 hover:border-white/[.2] hover:bg-[#222830] hover:shadow-[0_14px_35px_rgba(0,0,0,.2)]">
    <div className="mb-3 flex items-center justify-between"><span className={`mono text-[10px] font-medium ${task.priority === 1 ? "text-rose-300" : task.priority === 2 ? "text-amber-300" : "text-slate-500"}`}>{priorityLabels[task.priority - 1]} <span className="text-slate-600">·</span> {task.issueNumber ? `#${task.issueNumber}` : "LOCAL"}</span><StatusPill task={task} /></div>
    <h3 className="max-w-[245px] text-[13px] font-semibold leading-[1.42] text-slate-100">{task.title}</h3>
    <p className="mt-2 line-clamp-2 text-[11px] leading-relaxed text-slate-500">{task.currentSummary}</p>
    <div className="mt-4 flex items-center justify-between border-t border-white/[.06] pt-3"><div className="flex min-w-0 items-center gap-3"><span className={`flex shrink-0 items-center gap-1.5 text-[10px] ${agentTone(task.agentState)}`}><span className={`h-1.5 w-1.5 rounded-full ${task.agentState === "running" ? "live-pulse bg-lime-300" : task.agentState === "succeeded" ? "bg-violet-300" : task.agentState === "failed" ? "bg-red-300" : "bg-slate-600"}`} />{agentLabel(task.agentState)}</span><span className="mono truncate text-[10px] text-slate-500" title="Estimated agent cost">Est. {formatEstimatedCost(task.estimatedCostUsd)}</span><span className={`mono hidden truncate text-[10px] sm:inline ${task.actualCostStatus === "available" || task.actualCostStatus === "partial" ? "text-cyan-200" : task.actualCostStatus === "pending" ? "text-amber-200" : "text-slate-600"}`} title="Actual agent cost">{actualCostLabel(task)}</span></div><button onClick={(event) => { event.stopPropagation(); onStart(); }} disabled={task.status === "done" || task.agentState === "running"} className="flex shrink-0 items-center gap-1 rounded-lg border border-white/[.08] px-2 py-1 text-[10px] font-semibold text-slate-300 opacity-0 transition group-hover:opacity-100 hover:border-lime-300/30 hover:bg-lime-300/10 hover:text-lime-200 disabled:cursor-not-allowed disabled:opacity-30"><Icon name={task.agentState === "running" ? "loader" : "spark"} size={11} />{task.agentState === "running" ? "Live" : "Run"}</button></div>
  </article>;
}

function Modal({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: React.ReactNode }) {
  return <div className="modal-backdrop fixed inset-0 z-30 flex items-center justify-center p-5"><div className="w-full max-w-lg overflow-hidden rounded-3xl border border-white/[.12] bg-[#1a1f25] shadow-[0_30px_90px_rgba(0,0,0,.55)]"><div className="flex items-start justify-between border-b border-white/[.08] p-6"><div><div className="eyebrow text-lime-300/70">{eyebrow}</div><h2 className="mt-2 text-xl font-bold tracking-tight">{title}</h2></div><button onClick={onClose} className="rounded-xl p-2 text-slate-500 hover:bg-white/[.06] hover:text-white"><Icon name="x" size={18} /></button></div>{children}</div></div>;
}

function RunHistoryModal({ task, project, run, events, onClose }: { task: Task; project: Project; run: AgentRun; events: RunEvent[]; onClose: () => void }) {
  const dialogRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previousOverflow = document.body.style.overflow;
    const previousActiveElement = document.activeElement as HTMLElement | null;
    const handleKeyDown = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", handleKeyDown);
    dialogRef.current?.focus();
    return () => { document.body.style.overflow = previousOverflow; document.removeEventListener("keydown", handleKeyDown); previousActiveElement?.focus(); };
  }, []);
  return <div className="modal-backdrop fixed inset-0 z-30 flex items-center justify-center p-3 sm:p-6" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div ref={dialogRef} role="dialog" aria-modal="true" aria-labelledby="live-history-title" tabIndex={-1} className="flex max-h-[calc(100vh-1.5rem)] w-full max-w-6xl flex-col overflow-hidden rounded-3xl border border-cyan-300/15 bg-[#171b20] shadow-[0_30px_100px_rgba(0,0,0,.65)] outline-none sm:max-h-[calc(100vh-3rem)]"><div className="flex items-start justify-between gap-4 border-b border-white/[.08] p-5 sm:p-7"><div className="min-w-0"><div className="eyebrow text-cyan-200/70">{project.name} · {task.issueNumber ? `Issue #${task.issueNumber}` : "Local task"}</div><h2 id="live-history-title" className="mt-2 truncate text-xl font-bold tracking-tight text-slate-100 sm:text-2xl">Live history</h2><p className="mt-1 truncate text-xs text-slate-500">{task.title}</p></div><button type="button" onClick={onClose} aria-label="Close live history" className="shrink-0 rounded-xl p-2 text-slate-500 transition hover:bg-white/[.06] hover:text-white"><Icon name="x" size={19} /></button></div><div className="scrollbar min-h-0 overflow-y-auto p-3 sm:p-5"><RunConsole run={run} events={events} expanded /></div></div></div>;
}

function NewTaskModal({ project, onClose, onCreated }: { project: Project; onClose: () => void; onCreated: (warning?: string) => void }) {
  const [title, setTitle] = useState(""); const [description, setDescription] = useState(""); const [estimatedCostUsd, setEstimatedCostUsd] = useState(""); const [priority, setPriority] = useState("3"); const [loading, setLoading] = useState(false); const [error, setError] = useState("");
  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!title.trim()) return;
    setLoading(true);
    setError("");
    const response = await fetch("/api/tasks", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ projectId: project.id, title, description, estimatedCostUsd, priority: Number(priority), status: "inbox" }) });
    const result = await response.json().catch(() => ({})) as { error?: string; syncWarning?: string | null };
    setLoading(false);
    if (!response.ok) { setError(result.error ?? "Could not create task."); return; }
    onCreated(result.syncWarning ?? undefined);
  }
  return <Modal eyebrow="Human input · New task" title={`Add to ${project.name}`} onClose={onClose}><form onSubmit={submit} className="space-y-5 p-6"><label className="block"><span className="eyebrow">Task title</span><input autoFocus value={title} onChange={(e) => setTitle(e.target.value)} placeholder="What should the agent or you work on next?" className="mt-2 w-full rounded-xl border border-white/[.1] bg-black/20 px-3.5 py-3 text-sm text-white outline-none placeholder:text-slate-600 focus:border-lime-300/50" /></label><label className="block"><span className="eyebrow">Context</span><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Add acceptance criteria, constraints, or a useful starting point…" rows={4} className="mt-2 w-full resize-none rounded-xl border border-white/[.1] bg-black/20 px-3.5 py-3 text-sm leading-relaxed text-white outline-none placeholder:text-slate-600 focus:border-lime-300/50" /></label><label className="block"><span className="eyebrow">Estimated agent cost <span className="text-slate-700">· USD</span></span><input type="number" min="0" step="0.01" value={estimatedCostUsd} onChange={(e) => setEstimatedCostUsd(e.target.value)} placeholder="0.00" className="mono mt-2 w-full rounded-xl border border-white/[.1] bg-black/20 px-3.5 py-3 text-xs text-white outline-none placeholder:text-slate-600 focus:border-lime-300/50" /></label><label className="block"><span className="eyebrow">Priority</span><select value={priority} onChange={(e) => setPriority(e.target.value)} className="mt-2 w-full rounded-xl border border-white/[.08] bg-[#161a1f] px-3.5 py-3 text-sm text-white outline-none focus:border-lime-300/50"><option value="1">P1 · Critical</option><option value="2">P2 · High</option><option value="3">P3 · Normal</option><option value="4">P4 · Low</option></select></label>{error && <p className="rounded-xl border border-rose-300/20 bg-rose-300/10 p-3 text-xs text-rose-200">{error}</p>}<button disabled={loading || !title.trim()} className="flex w-full items-center justify-center gap-2 rounded-xl bg-lime-300 px-4 py-3 text-sm font-bold text-[#11150f] transition hover:bg-lime-200 disabled:cursor-not-allowed disabled:opacity-40"><Icon name="plus" size={16} />{loading ? "Creating…" : "Create task"}</button></form></Modal>;
}

function NewProjectModal({ onClose, onCreated }: { onClose: () => void; onCreated: () => void }) {
  const [fullName, setFullName] = useState(""); const [localPath, setLocalPath] = useState("~/Documents/Repos/"); const [githubProjectId, setGithubProjectId] = useState(""); const [description, setDescription] = useState(""); const [loading, setLoading] = useState(false); const [error, setError] = useState("");
  async function submit(event: FormEvent) { event.preventDefault(); setLoading(true); setError(""); const response = await fetch("/api/projects", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ fullName, localPath, githubProjectId, description }) }); if (!response.ok) { const result = await response.json(); setError(result.error ?? "Could not add repository."); setLoading(false); return; } setLoading(false); onCreated(); }
  return <Modal eyebrow="Workspace registry · New project" title="Add a repository" onClose={onClose}><form onSubmit={submit} className="space-y-5 p-6"><label className="block"><span className="eyebrow">GitHub repository</span><div className="relative mt-2"><Icon name="github" size={15} className="absolute left-3.5 top-3.5 text-slate-600" /><input autoFocus value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="owner/repository" className="w-full rounded-xl border border-white/[.1] bg-black/20 py-3 pl-10 pr-3.5 text-sm text-white outline-none placeholder:text-slate-600 focus:border-lime-300/50" /></div></label><label className="block"><span className="eyebrow">Local checkout</span><input value={localPath} onChange={(e) => setLocalPath(e.target.value)} className="mono mt-2 w-full rounded-xl border border-white/[.1] bg-black/20 px-3.5 py-3 text-xs text-white outline-none focus:border-lime-300/50" /></label><label className="block"><span className="eyebrow">Projects V2 node ID <span className="text-slate-700">· optional in demo</span></span><input value={githubProjectId} onChange={(e) => setGithubProjectId(e.target.value)} placeholder="PVT_kwDO…" className="mono mt-2 w-full rounded-xl border border-white/[.1] bg-black/20 px-3.5 py-3 text-xs text-white outline-none placeholder:text-slate-600 focus:border-lime-300/50" /></label><label className="block"><span className="eyebrow">What is this project?</span><textarea value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Optional context for the dashboard…" rows={3} className="mt-2 w-full resize-none rounded-xl border border-white/[.1] bg-black/20 px-3.5 py-3 text-sm leading-relaxed text-white outline-none placeholder:text-slate-600 focus:border-lime-300/50" /></label>{error && <p className="rounded-xl border border-rose-300/20 bg-rose-300/10 p-3 text-xs text-rose-200">{error}</p>}<button disabled={loading || !fullName.includes("/") || !localPath.trim()} className="flex w-full items-center justify-center gap-2 rounded-xl bg-lime-300 px-4 py-3 text-sm font-bold text-[#11150f] transition hover:bg-lime-200 disabled:cursor-not-allowed disabled:opacity-40"><Icon name="link" size={16} />{loading ? "Registering…" : "Register repository"}</button></form></Modal>;
}

function DetailRail({ task, project, runs, activity, runEvents, runtime, onClose, onStart, onStop, onContinue, onStatus, onCost, onComment }: { task: Task | null; project?: Project; runs: AgentRun[]; activity: ActivityItem[]; runEvents: RunEvent[]; runtime: DashboardData["runtime"]; onClose: () => void; onStart: (task: Task, reasoningEffort: ReasoningEffort | null) => void; onStop: (run: AgentRun) => void; onContinue: (run: AgentRun, reasoningEffort: ReasoningEffort | null) => void; onStatus: (status: TaskStatus) => void; onCost: (cost: string) => Promise<boolean>; onComment: (comment: string) => void }) {
  const [comment, setComment] = useState("");
  const [cost, setCost] = useState("");
  const [savingCost, setSavingCost] = useState(false);
  const [reasoningEffort, setReasoningEffort] = useState<ReasoningEffort | "">("");
  const [historyOpen, setHistoryOpen] = useState(false);
  useEffect(() => setCost(task ? task.estimatedCostUsd.toFixed(2) : ""), [task?.id, task?.estimatedCostUsd]);
  useEffect(() => setReasoningEffort(""), [task?.id]);
  useEffect(() => setHistoryOpen(false), [task?.id]);
  const currentRun = task ? runs.find((run) => run.taskId === task.id && ["running", "queued"].includes(run.status)) ?? runs.find((run) => run.taskId === task.id) : undefined;
  const currentEvents = currentRun ? runEvents.filter((event) => event.runId === currentRun.id) : [];
  const currentRunLabel = currentRun?.isActive ? "Live run" : currentRun?.executionMode === "demo" ? "Demo run" : currentRun ? "Live history" : "Last run";
  if (!task || !project) return <aside className="detail-rail flex min-h-[680px] flex-col items-center justify-center rounded-3xl border border-dashed border-white/[.1] bg-[#171b20]/50 p-8 text-center"><div className="mb-4 flex h-12 w-12 items-center justify-center rounded-2xl border border-white/[.08] bg-white/[.03] text-slate-600"><Icon name="layers" size={22} /></div><p className="text-sm font-semibold text-slate-300">Select a task to inspect</p><p className="mt-2 max-w-[220px] text-xs leading-relaxed text-slate-600">Choose a card to view its context, run history, and the latest agent checkpoint.</p></aside>;
  const taskActivity = activity.filter((item) => item.taskId === task.id).slice(0, 6);
  return <><aside className="detail-rail min-h-[680px] overflow-hidden rounded-3xl border border-white/[.1] bg-[#171b20]/90 shadow-[0_20px_70px_rgba(0,0,0,.18)]">
    <div className="flex items-start justify-between border-b border-white/[.08] p-5"><div className="flex gap-3"><ProjectMark project={project} /><div><div className="eyebrow">Task detail</div><div className="mt-1 max-w-[240px] text-sm font-bold leading-snug text-slate-100">{task.title}</div><div className="mono mt-1 text-[10px] text-slate-600">{task.issueNumber ? `#${task.issueNumber}` : "LOCAL TASK"} · {project.name}</div></div></div><button onClick={onClose} className="rounded-lg p-1 text-slate-600 hover:bg-white/[.05] hover:text-white"><Icon name="x" size={16} /></button></div>
    <div className="scrollbar max-h-[calc(100vh-190px)] overflow-y-auto p-5">
      <div className="flex items-center justify-between"><StatusPill task={task} /><select value={task.status} onChange={(e) => onStatus(e.target.value as TaskStatus)} className="rounded-lg border border-white/[.08] bg-[#22272e] px-2 py-1.5 text-[10px] text-slate-300 outline-none"><option value="inbox">Move to Inbox</option><option value="ready">Move to Ready</option><option value="in_progress">In progress</option><option value="human_review">Review</option><option value="blocked">Blocked</option><option value="done">Done</option></select></div>
      <p className="mt-5 text-xs leading-[1.7] text-slate-400">{task.description || "No additional task context yet."}</p>
      <form onSubmit={async (event) => { event.preventDefault(); setSavingCost(true); const saved = await onCost(cost); setSavingCost(false); if (saved) setCost(Number(cost || 0).toFixed(2)); }} className="mt-5 rounded-2xl border border-cyan-300/15 bg-cyan-300/[.045] p-4"><div className="flex items-start justify-between gap-3"><div><div className="eyebrow text-cyan-200/80">Estimated agent cost</div><p className="mt-1 text-[10px] leading-relaxed text-slate-500">Planning estimate, not a provider invoice.</p></div><span className="mono text-sm font-semibold text-cyan-200">{formatEstimatedCost(task.estimatedCostUsd)}</span></div><div className="mt-3 flex items-center justify-between gap-3 border-t border-cyan-300/10 pt-3"><div><div className="eyebrow text-cyan-200/60">Actual agent cost</div><p className="mt-1 text-[10px] leading-relaxed text-slate-500">{task.actualCostStatus === "available" ? "Provider/model-aware usage total." : task.actualCostStatus === "partial" ? "Some runs are not priced yet." : task.actualCostStatus === "pending" ? "Waiting for the active run usage." : task.actualCostStatus === "unavailable" ? "Provider usage or pricing was unavailable." : "No agent usage recorded yet."}</p></div><span className="mono text-sm font-semibold text-cyan-200">{task.actualCostUsd === null ? "—" : formatActualCost(task.actualCostUsd)}</span></div><div className="mt-3 flex gap-2"><input value={cost} onChange={(e) => setCost(e.target.value)} inputMode="decimal" aria-label="Estimated agent cost" className="mono min-w-0 flex-1 rounded-lg border border-white/[.08] bg-black/20 px-2.5 py-2 text-xs text-slate-200 outline-none focus:border-cyan-300/30" /><button type="submit" disabled={savingCost} className="rounded-lg border border-cyan-300/20 px-3 text-[10px] font-bold text-cyan-200 hover:bg-cyan-300/10 disabled:opacity-40">{savingCost ? "Saving…" : "Save"}</button></div></form>
      <div className="mt-5 flex gap-2">{currentRun?.isActive ? <button onClick={() => onStop(currentRun)} className="flex flex-1 items-center justify-center gap-2 rounded-xl border border-rose-300/25 bg-rose-300/10 px-3 py-2.5 text-xs font-bold text-rose-200 hover:bg-rose-300/15"><Icon name="stop" size={14} />Stop agent</button> : <button onClick={() => onStart(task, reasoningEffort || null)} disabled={task.status === "done"} className="flex flex-1 items-center justify-center gap-2 rounded-xl bg-lime-300 px-3 py-2.5 text-xs font-bold text-[#10140d] hover:bg-lime-200 disabled:opacity-40"><Icon name="spark" size={14} />{task.status === "human_review" ? "Continue implementation" : task.agentState === "succeeded" ? "Run again" : "Start agent"}</button>}{task.prUrl && <a href={task.prUrl} target="_blank" rel="noreferrer" aria-label="Open pull request for human review" className="flex items-center justify-center rounded-xl border border-white/[.1] px-3 text-slate-400 hover:border-violet-300/30 hover:text-violet-200"><Icon name="arrow-up-right" size={15} /></a>}</div>
      {currentRun && <><div className="mt-5 rounded-2xl border border-white/[.08] bg-black/15 p-4"><div className="flex items-center justify-between"><span className="eyebrow">{currentRunLabel}</span><span className="mono text-[10px] text-slate-500">{currentRun.progress}%</span></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-white/[.08]"><div className="h-full rounded-full bg-gradient-to-r from-lime-300 to-cyan-300 transition-all duration-700" style={{ width: `${currentRun.progress}%` }} /></div><p className="mt-3 text-[11px] leading-relaxed text-slate-400">{currentRun.currentActivity}</p>{currentRun.status !== "running" && currentRun.status !== "queued" && <button onClick={() => onContinue(currentRun, reasoningEffort || currentRun.reasoningEffort)} className="mt-3 flex items-center gap-1.5 text-[10px] font-semibold text-cyan-300 hover:text-cyan-200"><Icon name="command" size={12} />Continue this run</button>}</div><RunConsole run={currentRun} events={currentEvents} onExpand={() => setHistoryOpen(true)} /></>}
      <div className="mt-6"><div className="flex items-center justify-between"><span className="eyebrow">Human context</span><span className="mono text-[9px] text-slate-600">{runtime.executionMode === "live" ? "PUBLISHES TO GITHUB" : "LOCAL ONLY IN DEMO"}</span></div><div className="mt-2 flex gap-2"><textarea value={comment} onChange={(e) => setComment(e.target.value)} rows={2} placeholder="Add a constraint or next instruction…" className="min-w-0 flex-1 resize-none rounded-xl border border-white/[.08] bg-black/15 px-3 py-2.5 text-[11px] text-slate-200 outline-none placeholder:text-slate-600 focus:border-rose-300/35" /><button onClick={() => { if (comment.trim()) { onComment(comment.trim()); setComment(""); } }} disabled={!comment.trim()} className="self-stretch rounded-xl border border-rose-300/20 bg-rose-300/10 px-2.5 text-rose-200 hover:bg-rose-300/15 disabled:opacity-30"><Icon name="arrow-up-right" size={14} /></button></div></div>
      <div className="mt-7"><div className="eyebrow">Recent activity</div><div className="mt-3 space-y-3">{taskActivity.length ? taskActivity.map((item) => <div key={item.id} className="flex gap-3"><ActivityIcon item={item} /><div className="min-w-0"><div className="text-[11px] font-semibold text-slate-300">{item.title}</div><div className="mt-1 text-[10px] leading-relaxed text-slate-600">{item.detail}</div><div className="mono mt-1 text-[9px] text-slate-700">{formatRelativeTime(item.createdAt)}</div></div></div>) : <p className="text-xs text-slate-600">No local events yet.</p>}</div></div>
      {(task.branchName || task.prUrl) && <div className="mt-7 border-t border-white/[.08] pt-5"><div className="eyebrow">Human handoff</div>{task.branchName && <div className="mt-3 flex items-center gap-2 text-[11px] text-slate-400"><Icon name="git-branch" size={13} className="text-cyan-300" /><span className="mono truncate">{task.branchName}</span></div>}{task.prUrl && <a href={task.prUrl} target="_blank" rel="noreferrer" className="mt-2 flex items-center gap-2 text-[11px] text-violet-300 hover:text-violet-200"><Icon name="github" size={13} />Open pull request for review <Icon name="arrow-up-right" size={11} /></a>}</div>}
    </div>
  </aside>{historyOpen && currentRun && <RunHistoryModal task={task} project={project} run={currentRun} events={currentEvents} onClose={() => setHistoryOpen(false)} />}</>;
}

export default function ControlPlane() {
  const [data, setData] = useState<DashboardData>(EMPTY_DATA); const [selectedProjectId, setSelectedProjectId] = useState(""); const [selectedTaskId, setSelectedTaskId] = useState<string | null>(null); const [loading, setLoading] = useState(true); const [syncing, setSyncing] = useState(false); const [modal, setModal] = useState<"task" | "project" | null>(null); const [toast, setToast] = useState("");
  const load = async () => { const response = await fetch("/api/dashboard", { cache: "no-store" }); if (response.ok) { const next = await response.json() as DashboardData; setData(next); setSelectedProjectId((current) => current || next.projects[0]?.id || ""); setSelectedTaskId((current) => current || next.tasks.find((task) => task.projectId === (next.projects[0]?.id ?? ""))?.id || null); } setLoading(false); };
  useEffect(() => { void load(); const timer = setInterval(() => void load(), 4500); return () => clearInterval(timer); }, []);
  const project = data.projects.find((item) => item.id === selectedProjectId) ?? data.projects[0];
  const projectTasks = useMemo(() => data.tasks.filter((task) => task.projectId === project?.id), [data.tasks, project?.id]);
  const selectedTask = data.tasks.find((task) => task.id === selectedTaskId) ?? null;
  const selectedRuns = data.runs.filter((run) => run.taskId === selectedTask?.id);
  const activeRuns = data.runs.filter((run) => run.isActive);
  const openTasks = data.tasks.filter((task) => task.status !== "done").length;
  const reviewTasks = data.tasks.filter((task) => task.status === "human_review").length;
  const blockedTasks = data.tasks.filter((task) => task.status === "blocked").length;
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(""), 2600); };
  async function startTask(task: Task, reasoningEffort: ReasoningEffort | null = null) { const mode = task.agentState === "succeeded" || task.agentState === "waiting" ? "continue" : "start"; const response = await fetch(`/api/tasks/${task.id}/runs`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ mode, reasoningEffort }) }); if (!response.ok) { const body = await response.json(); notify(body.error ?? "Could not start the agent."); return; } setSelectedTaskId(task.id); notify(data.runtime.executionMode === "demo" ? "Demo run started · no repository changes will be made" : "Live agent claimed the task · watching workspace events"); await load(); }
  async function stopRun(run: AgentRun) { await fetch(`/api/runs/${run.id}/stop`, { method: "POST" }); notify("Agent stopped · workspace preserved"); await load(); }
  async function continueRun(run: AgentRun, reasoningEffort: ReasoningEffort | null = run.reasoningEffort) { const response = await fetch(`/api/runs/${run.id}/continue`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ reasoningEffort }) }); if (!response.ok) { const body = await response.json().catch(() => ({})) as { error?: string }; notify(body.error ?? "This run cannot be continued yet."); return; } notify("Continuation turn queued"); await load(); }
  async function updateStatus(status: TaskStatus) {
    if (!selectedTask) return;
    const response = await fetch(`/api/tasks/${selectedTask.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ status }) });
    const result = await response.json().catch(() => ({})) as { error?: string };
    if (!response.ok) { notify(result.error ?? "Could not synchronize task status with GitHub."); return; }
    notify(`Moved to ${getColumnLabel(status)}${data.runtime.executionMode === "live" ? " · GitHub synchronized" : ""}`);
    await load();
  }
  async function updateCost(cost: string) { if (!selectedTask) return false; const response = await fetch(`/api/tasks/${selectedTask.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ estimatedCostUsd: cost }) }); const result = await response.json().catch(() => ({})) as { error?: string }; if (!response.ok) { notify(result.error ?? "Could not save the estimated cost."); return false; } notify("Estimated task cost updated"); await load(); return true; }
  async function addComment(comment: string) { if (!selectedTask) return; await fetch(`/api/tasks/${selectedTask.id}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ comment }) }); notify("Human context added to the task"); await load(); }
  async function syncProject() {
    if (!project) return;
    setSyncing(true);
    const response = await fetch(`/api/projects/${project.id}/sync`, { method: "POST" });
    const result = await response.json().catch(() => ({})) as { error?: string; count?: number; imported?: number; updated?: number; repairedIssues?: number; createdIssues?: number; correctedIssues?: number; addedProjectItems?: number; mode?: string };
    setSyncing(false);
    if (!response.ok) { notify(result.error ?? "GitHub sync failed."); return; }
    const repairText = result.repairedIssues ? ` · repaired ${result.repairedIssues} issue${result.repairedIssues === 1 ? "" : "s"}` : "";
    const identityText = result.createdIssues || result.correctedIssues || result.addedProjectItems
      ? ` · ${result.createdIssues ?? 0} Issues created, ${result.correctedIssues ?? 0} links corrected, ${result.addedProjectItems ?? 0} Project items added`
      : "";
    notify(result.mode === "demo" ? "Demo sync completed · no GitHub requests made" : `GitHub sync completed · ${result.count ?? 0} tasks (${result.imported ?? 0} imported, ${result.updated ?? 0} updated)${identityText}${repairText}`);
    await load();
  }
  if (loading) return <div className="flex min-h-screen items-center justify-center bg-[#101318] text-slate-500"><div className="flex items-center gap-3 text-sm"><Icon name="loader" className="animate-spin text-lime-300" />Warming up the control plane…</div></div>;
  return <div className="app-shell"><div className="noise" /><aside className="nav-rail fixed bottom-0 left-0 top-0 z-10 flex w-[76px] flex-col items-center border-r border-white/[.08] bg-[#14181d]/75 py-5 backdrop-blur-xl"><div className="flex h-10 w-10 items-center justify-center rounded-[13px] bg-lime-300 text-[#101318] shadow-[0_0_28px_rgba(201,255,107,.2)]"><Icon name="command" size={21} strokeWidth={2.2} /></div><div className="mt-12 flex flex-col items-center gap-4"><button title="Overview" className="flex h-10 w-10 items-center justify-center rounded-xl bg-white/[.08] text-lime-300"><Icon name="grid" size={18} /></button><button title="Activity" className="flex h-10 w-10 items-center justify-center rounded-xl text-slate-600 transition hover:bg-white/[.05] hover:text-slate-300"><Icon name="activity" size={19} /></button><button title="Repositories" className="flex h-10 w-10 items-center justify-center rounded-xl text-slate-600 transition hover:bg-white/[.05] hover:text-slate-300"><Icon name="layers" size={18} /></button></div><div className="mt-auto flex flex-col items-center gap-4"><button title="Search" className="flex h-10 w-10 items-center justify-center rounded-xl text-slate-600 hover:bg-white/[.05] hover:text-slate-300"><Icon name="search" size={18} /></button><button title="Settings" className="flex h-10 w-10 items-center justify-center rounded-xl text-slate-600 hover:bg-white/[.05] hover:text-slate-300"><Icon name="settings" size={18} /></button><div className="flex h-9 w-9 items-center justify-center rounded-full border border-white/[.12] bg-[#262d34] text-[10px] font-bold text-slate-300">ML</div></div></aside><main className="content-wrap ml-[76px] px-9 pb-12 pt-7"><header className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="eyebrow">Control plane</div><span className="h-1 w-1 rounded-full bg-slate-700" /><span className="mono text-[10px] text-slate-600">LOCAL / PERSONAL</span></div><div className="flex items-center gap-2"><div className={`hidden items-center gap-2 rounded-full border px-3 py-1.5 text-[10px] sm:flex ${data.runtime.executionMode === "live" ? "border-cyan-300/15 bg-cyan-300/[.05] text-cyan-200" : "border-amber-300/15 bg-amber-300/[.05] text-amber-200"}`}><span className={`h-1.5 w-1.5 rounded-full ${data.runtime.executionMode === "live" ? "bg-cyan-300" : "bg-amber-300"}`} />{data.runtime.executionMode === "live" ? "LIVE MODE" : "DEMO MODE"}</div><button onClick={() => setModal("project")} className="flex items-center gap-2 rounded-xl border border-white/[.1] bg-white/[.03] px-3 py-2 text-xs font-semibold text-slate-300 transition hover:border-lime-300/30 hover:text-lime-200"><Icon name="plus" size={14} />Add repository</button></div></header>{data.runtime.reason && <div className="mt-5 flex items-start gap-3 rounded-2xl border border-amber-300/15 bg-amber-300/[.05] px-4 py-3 text-[11px] leading-relaxed text-amber-100/70"><Icon name="pause" size={15} className="mt-0.5 shrink-0 text-amber-300" /><span><strong className="font-bold text-amber-200">Execution note:</strong> {data.runtime.reason}</span></div>}<section className="stagger mt-10 grid gap-8 xl:grid-cols-[1fr_360px]"><div><div className="eyebrow text-lime-300/80">Monday · 17 August 2026</div><h1 className="mt-3 max-w-[720px] text-[clamp(2.2rem,5vw,4.5rem)] font-extrabold leading-[.98] tracking-[-.065em] text-[#f3f5f0]">Keep every<br /><span className="text-slate-500">project moving.</span></h1><p className="mt-5 max-w-[540px] text-sm leading-relaxed text-slate-500">One quiet room for your repositories, your agents, and the human decisions that keep work pointed in the right direction.</p></div><div className="relative overflow-hidden rounded-3xl border border-lime-300/15 bg-gradient-to-br from-[#273323] to-[#1b211f] p-5 shadow-[0_15px_50px_rgba(0,0,0,.16)]"><div className="absolute -right-20 -top-24 h-60 w-60 rounded-full border border-lime-300/10" /><div className="absolute -right-8 -top-12 h-36 w-36 rounded-full border border-lime-300/10" /><div className="relative flex items-start justify-between"><div><div className="eyebrow text-lime-300/60">Operator brief</div><p className="mt-3 max-w-[240px] text-sm font-semibold leading-relaxed text-lime-50">{activeRuns.length ? `${activeRuns.length} agent ${activeRuns.length === 1 ? "is" : "are"} moving work right now.` : "All quiet. Pick a ready task when you are ready to make progress."}</p></div><div className="flex h-10 w-10 items-center justify-center rounded-2xl bg-lime-300 text-[#101318]"><Icon name="spark" size={19} /></div></div><div className="relative mt-8 flex items-center justify-between border-t border-lime-300/10 pt-3"><span className="mono text-[10px] text-lime-100/50">{data.projects.length} REPOSITORIES · {openTasks} OPEN TASKS</span><button onClick={() => project && setModal("task")} className="flex items-center gap-1 text-[10px] font-bold text-lime-200 hover:text-white">Add input <Icon name="arrow-up-right" size={12} /></button></div></div></section><section className="metrics-grid mt-9 grid grid-cols-4 gap-3"><Metric label="Open tasks" value={String(openTasks).padStart(2, "0")} detail="across repos" accent="#73d7ff" icon="inbox" /><Metric label="Agents live" value={String(activeRuns.length).padStart(2, "0")} detail="of 04 slots" accent="#c9ff6b" icon="bot" /><Metric label="Review queue" value={String(reviewTasks).padStart(2, "0")} detail="needs eyes" accent="#b9a5ff" icon="git-branch" /><Metric label="Blocked" value={String(blockedTasks).padStart(2, "0")} detail="needs input" accent="#ff8fa3" icon="pause" /></section><section className="mt-11"><div className="flex flex-wrap items-end justify-between gap-4"><div><div className="eyebrow">Workspace registry</div><h2 className="mt-2 text-xl font-bold tracking-tight text-slate-100">Your projects</h2></div><button onClick={() => void syncProject()} disabled={syncing || !project} className="flex items-center gap-2 text-xs font-semibold text-slate-500 transition hover:text-cyan-200 disabled:opacity-50"><Icon name="refresh" size={14} className={syncing ? "animate-spin" : ""} />{syncing ? "Syncing…" : `Sync ${project?.name ?? "project"}`}</button></div><div className="mt-4 flex gap-3 overflow-x-auto pb-1 scrollbar">{data.projects.map((item) => <button key={item.id} onClick={() => { setSelectedProjectId(item.id); setSelectedTaskId(data.tasks.find((task) => task.projectId === item.id)?.id ?? null); }} className={`flex min-w-[230px] items-center gap-3 rounded-2xl border p-3 text-left transition ${item.id === project?.id ? "border-white/[.18] bg-[#22282f]" : "border-white/[.07] bg-[#191d22]/65 hover:border-white/[.14]"}`}><ProjectMark project={item} /><span className="min-w-0 flex-1"><span className="block truncate text-xs font-bold text-slate-200">{item.name}</span><span className="mono mt-1 block truncate text-[9px] text-slate-600">{item.fullName}</span><span className="mono mt-1 block text-[8px] tracking-[.12em] text-slate-700">{item.isDemo ? "DEMO FIXTURE" : "MANAGED REPO"}</span></span><span className="flex flex-col items-end gap-1"><span className="flex items-center gap-1 text-[9px] text-slate-500"><span className={`h-1.5 w-1.5 rounded-full ${item.activeAgents ? "bg-lime-300" : "bg-slate-600"}`} />{item.activeAgents} live</span><span className="mono text-[9px] text-slate-600">{item.openTasks} open</span></span></button>)}<button onClick={() => setModal("project")} className="flex min-w-[130px] items-center justify-center gap-2 rounded-2xl border border-dashed border-white/[.12] text-xs font-semibold text-slate-600 transition hover:border-lime-300/30 hover:text-lime-200"><Icon name="plus" size={15} />Add project</button></div></section><section className="board-layout mt-7 grid grid-cols-[minmax(0,1fr)_370px] gap-4"><div className="min-w-0 rounded-3xl border border-white/[.1] bg-[#171b20]/80 p-5 shadow-[0_20px_70px_rgba(0,0,0,.14)]"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><ProjectMark project={project ?? { initials: "--", accent: "#667", id: "", name: "", fullName: "", description: "", localPath: "", defaultBranch: "main", githubProjectId: null, githubProjectUrl: null, isDemo: false, status: "attention", lastSyncedAt: "", activeAgents: 0, openTasks: 0, openPrs: 0 }} /><div><div className="eyebrow">Active board</div><h2 className="mt-1 text-sm font-bold text-slate-100">{project?.fullName}</h2></div></div><div className="flex items-center gap-2"><span className="mono hidden text-[9px] text-slate-600 sm:block">SYNCED {project ? formatRelativeTime(project.lastSyncedAt).toUpperCase() : "—"}</span><button onClick={() => project && setModal("task")} className="flex items-center gap-1.5 rounded-xl bg-lime-300 px-3 py-2 text-[11px] font-bold text-[#101318] hover:bg-lime-200"><Icon name="plus" size={13} />New task</button></div></div><div className="board-columns scrollbar mt-6 grid grid-cols-7 gap-3 overflow-x-auto pb-3">{BOARD_COLUMNS.map((column) => { const columnTasks = projectTasks.filter((task) => task.status === column.id); return <div key={column.id} className="min-w-[206px]"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2"><span className={`h-1.5 w-1.5 rounded-full ${statusStyles[column.id].dot}`} /><span className="text-[11px] font-bold text-slate-400">{column.label}</span><span className="mono text-[9px] text-slate-700">{String(columnTasks.length).padStart(2, "0")}</span></div><button className="text-slate-700 hover:text-slate-300"><Icon name="plus" size={13} /></button></div><div className="space-y-2.5">{columnTasks.map((task) => <TaskCard key={task.id} task={task} onSelect={() => setSelectedTaskId(task.id)} onStart={() => void startTask(task)} />)}{columnTasks.length === 0 && <div className="rounded-2xl border border-dashed border-white/[.07] py-7 text-center text-[10px] text-slate-700">No tasks</div>}</div></div>; })}</div></div><DetailRail task={selectedTask} project={data.projects.find((item) => item.id === selectedTask?.projectId)} runs={selectedRuns} activity={data.activity} runEvents={data.runEvents} runtime={data.runtime} onClose={() => setSelectedTaskId(null)} onStart={(task, effort) => void startTask(task, effort)} onStop={(run) => void stopRun(run)} onContinue={(run) => void continueRun(run)} onStatus={(status) => void updateStatus(status)} onCost={updateCost} onComment={(comment) => void addComment(comment)} /></section><section className="mt-7 grid gap-4 lg:grid-cols-[1.25fr_.75fr]"><div className="rounded-3xl border border-white/[.1] bg-[#171b20]/80 p-5"><div className="flex items-center justify-between"><div><div className="eyebrow">Cross-project stream</div><h2 className="mt-2 text-sm font-bold text-slate-100">What changed recently</h2></div><button className="mono text-[9px] text-slate-600 hover:text-slate-300">VIEW ALL <Icon name="arrow-up-right" size={10} className="inline" /></button></div><div className="mt-5 divide-y divide-white/[.06]">{data.activity.slice(0, 5).map((item) => <div key={item.id} className="flex gap-3 py-3 first:pt-0"><ActivityIcon item={item} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-baseline justify-between gap-2"><div className="text-xs font-semibold text-slate-300">{item.title}</div><span className="mono text-[9px] text-slate-700">{formatRelativeTime(item.createdAt)}</span></div><div className="mt-1 truncate text-[10px] text-slate-600">{item.detail}</div></div></div>)}{!data.activity.length && <p className="text-xs text-slate-600">No activity yet.</p>}</div></div><div className="rounded-3xl border border-white/[.1] bg-[#171b20]/80 p-5"><div className="eyebrow">Runtime posture</div><h2 className="mt-2 text-sm font-bold text-slate-100">Autonomy with a paper trail.</h2><p className="mt-3 text-xs leading-relaxed text-slate-500">Agents can edit, test, branch, and open PRs. Every meaningful checkpoint stays visible here and can be summarized back to the GitHub issue.</p><div className="mt-5 space-y-2"><div className="flex items-center gap-2 text-[10px] text-slate-400"><span className="flex h-5 w-5 items-center justify-center rounded-md bg-lime-300/10 text-lime-300"><Icon name="check" size={12} /></span>Isolated workspaces</div><div className="flex items-center gap-2 text-[10px] text-slate-400"><span className="flex h-5 w-5 items-center justify-center rounded-md bg-cyan-300/10 text-cyan-300"><Icon name="check" size={12} /></span>Automatic branch + PR handoff</div><div className="flex items-center gap-2 text-[10px] text-slate-400"><span className="flex h-5 w-5 items-center justify-center rounded-md bg-violet-300/10 text-violet-300"><Icon name="check" size={12} /></span>Human review checkpoints</div></div></div></section></main>{modal === "task" && project && <NewTaskModal project={project} onClose={() => setModal(null)} onCreated={(warning) => { setModal(null); notify(warning ?? "Task added to the board"); void load(); }} />}{modal === "project" && <NewProjectModal onClose={() => setModal(null)} onCreated={() => { setModal(null); notify("Repository added to the registry"); void load(); }} />}{toast && <div className="fixed bottom-6 left-1/2 z-40 flex -translate-x-1/2 items-center gap-2 rounded-full border border-lime-300/20 bg-[#222a22] px-4 py-2.5 text-xs font-semibold text-lime-100 shadow-[0_12px_40px_rgba(0,0,0,.4)]"><span className="h-1.5 w-1.5 rounded-full bg-lime-300" />{toast}</div>}</div>;
}